import { getEditorConfig } from "./config.js";
import { defineFormConfig, defineFormItem } from "@tmagic/form";
import { tMagicMessage } from "@tmagic/design";
//#region packages/editor/src/utils/code-block.ts
/** 默认的"参数类型"列配置：数字 / 字符串 / 组件 三选一。 */
var defaultParamColConfig = () => defineFormItem({
	type: "row",
	label: "参数类型",
	items: [{
		text: "参数类型",
		labelWidth: "70px",
		type: "select",
		name: "type",
		options: [
			{
				text: "数字",
				label: "数字",
				value: "number"
			},
			{
				text: "字符串",
				label: "字符串",
				value: "text"
			},
			{
				text: "组件",
				label: "组件",
				value: "ui-select"
			}
		]
	}]
});
/**
* 生成代码块表单配置。返回的是普通对象数组，可直接传给 `<MForm :config>`；
* 如需响应式的 props 变化（如切换 dataSourceType），调用方在 `computed` 中再次调用本函数即可。
*/
var getCodeBlockFormConfig = (options = {}) => {
	const { paramColConfig, isDataSource, dataSourceType, codeOptions = {}, editable = true } = options;
	return defineFormConfig([
		{
			text: "名称",
			name: "name",
			...editable ? { rules: [{
				required: true,
				message: "请输入名称",
				trigger: "blur"
			}] } : {}
		},
		{
			text: "描述",
			name: "desc"
		},
		{
			text: "执行时机",
			name: "timing",
			type: "select",
			options: () => {
				const list = [
					{
						text: "初始化前",
						value: "beforeInit"
					},
					{
						text: "初始化后",
						value: "afterInit"
					},
					{
						text: "页面渲染后",
						value: "mounted"
					}
				];
				if (dataSourceType?.() !== "base") {
					list.push({
						text: "请求前",
						value: "beforeRequest"
					});
					list.push({
						text: "请求后",
						value: "afterRequest"
					});
				}
				return list;
			},
			display: () => Boolean(isDataSource?.())
		},
		{
			type: "table",
			border: true,
			text: "参数",
			enableFullscreen: false,
			enableToggleMode: false,
			name: "params",
			dropSort: false,
			items: [
				{
					type: "text",
					label: "参数名",
					name: "name"
				},
				{
					type: "text",
					label: "描述",
					name: "extra"
				},
				paramColConfig || defaultParamColConfig()
			]
		},
		{
			name: "content",
			type: "vs-code",
			options: codeOptions,
			autosize: {
				minRows: 10,
				maxRows: 30
			},
			...editable ? { onChange: (_formState, code) => {
				try {
					getEditorConfig("parseDSL")(code);
					return code;
				} catch (error) {
					tMagicMessage.error(error.message);
					throw error;
				}
			} } : {}
		}
	]);
};
//#endregion
export { getCodeBlockFormConfig };
